-- În SSMS alegeți întâi baza flyableinc din lista de baze de deasupra editorului (Azure SQL nu acceptă USE).
SET NOCOUNT ON;

-- 0. Oprim scriptul dacă nu suntem în baza flyableinc (de exemplu în master)
IF DB_NAME() <> N'flyableinc'
BEGIN
    RAISERROR(N'Scriptul trebuie rulat în baza flyableinc. Alegeți-o din lista de baze din SSMS și rulați din nou.', 16, 1);
    SET NOEXEC ON;  -- loturile de mai jos nu se mai execută
END;
GO

SET NOCOUNT ON;
-- 1. Ștergem tabelele existente (întâi cele de fapte, din cauza cheilor externe)
DROP TABLE IF EXISTS dbo.Fact_Rezervari;
DROP TABLE IF EXISTS dbo.Fact_Zboruri;
DROP TABLE IF EXISTS dbo.Dim_Pasageri;
DROP TABLE IF EXISTS dbo.Dim_Canale;
DROP TABLE IF EXISTS dbo.Dim_Clase;
DROP TABLE IF EXISTS dbo.Dim_Aeronave;
DROP TABLE IF EXISTS dbo.Dim_Rute;
DROP TABLE IF EXISTS dbo.Dim_Companii;
DROP TABLE IF EXISTS dbo.Dim_Date;
GO

-- 2. Creăm tabelele noi: fără chei și fără constrângeri, ca un export brut din sistemele companiilor
CREATE TABLE dbo.Dim_Date (
    ID INT,
    Data NVARCHAR(10),
    An SMALLINT,
    Trimestru NVARCHAR(10),
    Luna TINYINT,
    Luna_Nume NVARCHAR(20),
    An_Luna CHAR(7),
    Zi_Saptamana NVARCHAR(10),
    Nr_Zi_Saptamana TINYINT,
    Weekend NVARCHAR(2),
    Sezon NVARCHAR(10),
    Observatii NVARCHAR(60)
);
CREATE TABLE dbo.Dim_Companii (
    ID INT,
    Companie NVARCHAR(60),
    Cod_IATA CHAR(2),
    Tip_Companie NVARCHAR(60),
    Tara NVARCHAR(30),
    Alianta NVARCHAR(20),
    An_Infiintare SMALLINT
);
CREATE TABLE dbo.Dim_Rute (
    ID INT,
    Cod_Ruta CHAR(7),
    Ruta NVARCHAR(60),
    Aeroport_Plecare CHAR(3),
    Oras_Plecare NVARCHAR(30),
    Tara_Plecare NVARCHAR(30),
    Aeroport_Sosire CHAR(3),
    Oras_Sosire NVARCHAR(30),
    Tara_Sosire NVARCHAR(40),
    Regiune_Sosire NVARCHAR(30),
    Distanta_km NVARCHAR(20),
    Durata_Min NVARCHAR(20),
    Tip_Ruta NVARCHAR(20),
    Latitudine_Sosire NVARCHAR(20),
    Longitudine_Sosire NVARCHAR(20),
    Observatii NVARCHAR(60)
);
CREATE TABLE dbo.Dim_Aeronave (
    ID INT,
    Inmatriculare NVARCHAR(10),
    Model NVARCHAR(30),
    Producator NVARCHAR(20),
    Locuri NVARCHAR(20),
    Tip_Aeronava NVARCHAR(20),
    Autonomie_km INT,
    An_Fabricatie SMALLINT
);
CREATE TABLE dbo.Dim_Clase (
    ID INT,
    Clasa NVARCHAR(20),
    Cod_Clasa CHAR(1),
    Bagaj_Inclus_kg NVARCHAR(20),
    Ordine TINYINT
);
CREATE TABLE dbo.Dim_Canale (
    ID INT,
    Canal NVARCHAR(30),
    Tip_Canal NVARCHAR(10),
    Comision_Pct NVARCHAR(10)
);
CREATE TABLE dbo.Dim_Pasageri (
    ID INT,
    Cod_Pasager CHAR(6),
    Gen CHAR(1),
    Grupa_Varsta NVARCHAR(10),
    Tara NVARCHAR(30),
    Oras NVARCHAR(60),
    Nivel_Loialitate NVARCHAR(60),
    An_Inscriere SMALLINT
);
CREATE TABLE dbo.Fact_Zboruri (
    ID_Zbor INT,
    Cod_Zbor NVARCHAR(8),
    ID_Date INT,
    ID_Companie INT,
    ID_Ruta INT,
    ID_Aeronava INT,
    Ora_Plecare TIME(0),
    Status_Zbor NVARCHAR(20),
    Intarziere_Min INT,
    Locuri_Disponibile INT,
    Pasageri_Imbarcati INT,
    Venit_Bilete NVARCHAR(20),
    Venit_Auxiliar NVARCHAR(20),
    Cost_Combustibil DECIMAL(12,2),
    Cost_Operare DECIMAL(12,2),
    Exportat_La NVARCHAR(20)
);
CREATE TABLE dbo.Fact_Rezervari (
    ID_Rezervare INT,
    Cod_Rezervare NVARCHAR(12),
    ID_Date INT,
    ID_Companie INT,
    ID_Ruta INT,
    ID_Clasa INT,
    ID_Canal INT,
    ID_Pasager NVARCHAR(20),
    Zile_Avans INT,
    Nr_Bilete NVARCHAR(20),
    Pret_Bilet DECIMAL(10,2),
    Taxe_Bilet DECIMAL(10,2),
    Bagaj_Extra DECIMAL(10,2),
    Valoare_Totala DECIMAL(12,2),
    Status_Rezervare NVARCHAR(20),
    Observatii NVARCHAR(60)
);
GO

